<script lang="ts">
	// @ts-expect-error — generated by Wails
	import { GetDisks } from '@wails/go/app/App.js';
	import { LogInfo, LogError } from '@wails/runtime/runtime';
	import PageLayout from '$components/PageLayout.svelte';
	import { diskSelectionData } from '$lib/store';
	import type { DiskInfo } from '$lib/types';
	import { formatSize } from '$lib/types';

	let disks = $state<DiskInfo[]>([]);
	let selectedDiskId = $state<string>('');
	let loading = $state(true);
	let error = $state<string | null>(null);

	async function loadDisks(): Promise<void> {
		try {
			disks = await GetDisks();
			if (disks.length === 0) {
				error = 'No disks found. Please connect a storage device.';
			}
		} catch (err) {
			error = `Failed to load disks: ${err instanceof Error ? err.message : String(err)}`;
			LogError(`[DiskSelectionPage] ${error}`);
		} finally {
			loading = false;
		}
	}

	function selectDisk(disk: DiskInfo): void {
		selectedDiskId = disk.path;
		diskSelectionData.set({ diskId: disk.path });
	}

	function onDiskSelect(disk: DiskInfo): void {
		LogInfo(`[DiskSelectionPage] Selected: ${disk.path} (${formatSize(disk.size)})`);
		selectDisk(disk);
	}

	loadDisks();
</script>

<PageLayout title="Select Installation Disk">
	<p class="hint">Choose a disk to install AestheticOS. All data on the selected disk will be erased.</p>

	{#if loading}
		<div class="loading-state">
			<p class="loading-text">Scanning for disks...</p>
		</div>
	{:else if error}
		<div class="error-state">
			<p class="error-text">{error}</p>
			<Button variant="secondary" onClick={loadDisks}>Retry</Button>
		</div>
	{:else if disks.length === 0}
		<div class="empty-state">
			<p class="empty-text">No storage devices found.</p>
		</div>
	{:else}
		<div class="disk-list">
			{#each disks as disk (disk.path)}
				<button
					type="button"
					class={['disk-card', { selected: selectedDiskId === disk.path }]}
					onclick={() => onDiskSelect(disk)}
				>
					<div class="disk-main">
						<div class="disk-icon">
							{#if disk.rotational}
								<span class="icon-hdd" title="Hard Disk Drive">💾</span>
							{:else}
								<span class="icon-ssd" title="Solid State Drive">⚡</span>
							{/if}
						</div>
						<div class="disk-info">
							<div class="disk-name">{disk.model}</div>
							<div class="disk-details">
								<span class="disk-size">{formatSize(disk.size)}</span>
								<span class="disk-divider">·</span>
								<span class="disk-type">{disk.rotational ? 'HDD' : 'SSD'}</span>
								{#if disk.trans}
									<span class="disk-divider">·</span>
									<span class="disk-trans">{disk.trans.toUpperCase()}</span>
								{/if}
							</div>
						</div>
						<div class="disk-radio">
							<div class={['radio', { checked: selectedDiskId === disk.path }]}>
								{#if selectedDiskId === disk.path}
									<span class="radio-dot"></span>
								{/if}
							</div>
						</div>
					</div>

					{#if disk.fstype}
						<div class="disk-extra">
							<span class="tag fstype-tag">Existing: {disk.fstype}</span>
						</div>
					{/if}
					{#if disk.mountpoint}
						<div class="disk-extra">
							<span class="tag mount-tag">Mounted: {disk.mountpoint}</span>
						</div>
					{/if}
					{#if disk.serial}
						<div class="disk-extra">
							<span class="tag serial-tag">S/N: {disk.serial}</span>
						</div>
					{/if}
				</button>
			{/each}
		</div>
	{/if}
</PageLayout>

